import type { Metadata } from "next";
import { getFeature, type FeatureSlug } from "./features";

/** The shared link-preview card, generated by app/opengraph-image.tsx. */
const OG_IMAGE = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  alt: "Concrete: make your understanding concrete. Built for CS and ACME students.",
};

/**
 * Per-page metadata. A page that sets `openGraph` replaces the root one
 * entirely, so the image has to be repeated here for every page.
 */
export function pageMetadata({ title, description, path }: { title: string; description: string; path: string }): Metadata {
  const full = `${title} — Concrete`;
  return {
    title,
    description,
    openGraph: { type: "website", siteName: "Concrete", url: path, title: full, description, images: [OG_IMAGE] },
    twitter: { card: "summary_large_image", title: full, description, images: [OG_IMAGE] },
  };
}

export function featureMetadata(slug: FeatureSlug): Metadata {
  const f = getFeature(slug);
  return pageMetadata({ title: f.name, description: `${f.headline} ${f.lede}`, path: `/${slug}` });
}
